async function test() {
  // Check WETH on Arbitrum One
  const wethArb = "0x82aF49447D8a07e3bd95BD0d56f35241523fBab1";
  const usdcArb = "0xaf88d065e77c8cC2239327C5EDb3A432268e5831";
  const usdceArb = "0xFF970A61A04b1cA14834A43f5dE4533eBDDB5CC8";

  // Call name() and symbol() on Arb1
  for (const [name, addr] of [["WETH", wethArb], ["USDC", usdcArb], ["USDC.e", usdceArb]]) {
    const res = await fetch("https://arb1.arbitrum.io/rpc", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        jsonrpc: "2.0",
        id: 1,
        method: "eth_call",
        params: [{ to: addr, data: "0x95d89b41" }, "latest"] // symbol()
      })
    }).then(r => r.json());
    console.log("Arb One", name, addr, res.result);
  }
}
test();
'

