		MaxCodeSize:               arbChainParams.MaxCodeSize,
		MaxInitCodeSize:           arbChainParams.MaxInitCodeSize,
		MaxUncompressedBatchSize:  arbChainParams.MaxUncompressedBatchSize,
	}
}

